window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ae5a191cc3ae1eef"]={"versions": [{"id": "FIG-ae5a191cc3ae1eef", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd SporadicFrame</code>) zur Darstellung der Interaktion zwischen PDU Router (<code>PduR</code>) und LIN Interface (<code>LinIf</code>) im AUTOSAR Classic Platform Communication Stack. Das Diagramm spezifiziert die PDU-Übertragungsanforderung für sporadische Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind die BSW-Module <code>PduR::PduR</code> und <code>LinIf::LinIf</code>, jeweils modelliert als UML-Lebenslinie mit Ausführungsbalken (Execution Specification). Die Schnittstelle zwischen den Modulen ist die synchrone C-API-Funktion <code>LinIf_Transmit(LinTxPduId, PduInfoPtr) :Std_ReturnType</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>PduR::PduR</code> initiiert die Übertragung eines sporadischen Frames durch den synchronen Aufruf <code>LinIf_Transmit(LinTxPduId, PduInfoPtr)</code> an <code>LinIf::LinIf</code>.\n</li><li><code>LinIf::LinIf</code> führt eine interne Prüfung der PDU-Identifikation (<code>CheckId</code>) über einen internen Selbstaufruf durch.\n</li><li>Nach erfolgreicher Identifikationsprüfung setzt <code>LinIf::LinIf</code> über einen weiteren internen Selbstaufruf ein internes Sende-Flag (<code>SetFlag</code>), um die PDU für den nächsten Sendezyklus des Sporadic Frame Schedule Tables vorzumerken.\n</li><li><code>LinIf::LinIf</code> kehrt über einen gestrichelten Antwortpfeil (<code>LinIf_Transmit</code>) synchron zu <code>PduR::PduR</code> zurück und liefert den Rückgabewert vom Typ <code>Std_ReturnType</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dokumentiert den synchronen Teil der Übertragung sporadischer LIN-Frames: <code>LinIf_Transmit</code> führt bei sporadischen Frames nicht zum unmittelbaren Bustransfer, sondern registriert die Sendeanforderung lediglich modul-intern (<code>SetFlag</code>). Die tatsächliche Busübertragung erfolgt asynchron über das LIN-Scheduling.</p>"}, {"id": "FIG-1e8be47c60c6b9bf", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd SporadicFrame</code>) zur Darstellung der Interaktion zwischen PDU Router (<code>PduR</code>) und LIN Interface (<code>LinIf</code>) im AUTOSAR Classic Platform Communication Stack. Das Diagramm spezifiziert die PDU-Übertragungsanforderung für sporadische Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind die BSW-Module <code>«module» PduR::PduR</code> und <code>«module» LinIf::LinIf</code>, jeweils modelliert als UML-Lebenslinie mit Ausführungsbalken. Die Schnittstelle zwischen den Modulen ist die synchrone Funktion <code>LinIf_Transmit(LinTxPduId, PduInfoPtr, return)</code>. Am unteren Bildrand befindet sich eine Notizbox mit Metadaten (<code>Status:Proposed by WPII-2.1.1 as per LinIf SWS 1.1.2</code>, <code>Description:</code>, <code>Comments:</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>PduR::PduR</code> initiiert die Übertragung eines sporadischen Frames über den synchronen Aufruf <code>LinIf_Transmit(LinTxPduId, PduInfoPtr, return)</code> an <code>LinIf::LinIf</code>.\n</li><li><code>LinIf::LinIf</code> führt eine interne Prüfung der PDU-Identifikation (<code>CheckId</code>) über einen Selbstaufruf aus.\n</li><li>Über einen weiteren internen Selbstaufruf setzt <code>LinIf::LinIf</code> das Sende-Flag (<code>SetFlag</code>) für den sporadischen Frame.\n</li><li><code>LinIf::LinIf</code> kehrt über eine unbeschriftete gestrichelte Antwortnachricht synchron zu <code>PduR::PduR</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dokumentiert den synchronen Teil der Übertragung sporadischer LIN-Frames: <code>LinIf_Transmit</code> führt bei sporadischen Frames nicht zum unmittelbaren Bustransfer, sondern registriert die Sendeanforderung lediglich modul-intern (<code>SetFlag</code>). Die tatsächliche Busübertragung erfolgt asynchron über das LIN-Scheduling.</p>"}, {"id": "FIG-4fbcaf8bb89ecc05", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Notizkommentar / Metadaten-Fragment zur Spezifikation des LIN Interface (<code>LinIf</code>). Es ist kein Sequenzdiagramm oder Verhaltensablauf abgebildet.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Es sind keine Software-Komponenten, BSW-Module, Lebenslinien oder Programmierschnittstellen dargestellt. Das Bild zeigt ausschließlich ein Notizfeld mit den Feldern <code>Status:Proposed by WPII-2.1.1 as per LinIf SWS 1.1.2</code>, <code>Description:</code> und <code>Comments:</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm enthält keine dynamischen Abläufe, Funktionsaufrufe oder Nachrichtenfolgen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Bildfassung stellt keinen normativen Verhaltensablauf dar, sondern enthält lediglich ein Dokumentations- oder Änderungsnotizfeld ohne spezifizierte Schnittstellen- oder Verhaltensdetails.</p>"}], "trans": [{"from": "FIG-ae5a191cc3ae1eef", "to": "FIG-1e8be47c60c6b9bf", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Stereotyp: Die Lebenslinienköpfe <code>PduR::PduR</code> und <code>LinIf::LinIf</code> erhalten das Stereotyp <code>«module»</code>.\n</li><li>Operationssignatur: Der synchrone Aufruf wechselt in der Notation von <code>LinIf_Transmit(LinTxPduId, PduInfoPtr) :Std_ReturnType</code> zu <code>LinIf_Transmit(LinTxPduId, PduInfoPtr, return)</code>.\n</li><li>Rückkehrpfeil: Die Beschriftung <code>LinIf_Transmit</code> am gestrichelten Rückkehrpfeil entfällt.\n</li><li>Metadatenbox: Ein Kommentarblock mit den Feldern <code>Status:Proposed by WPII-2.1.1 as per LinIf SWS 1.1.2</code>, <code>Description:</code> und <code>Comments:</code> ist unten links eingefügt.\n</li></ul>"}, {"from": "FIG-1e8be47c60c6b9bf", "to": "FIG-4fbcaf8bb89ecc05", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Diagramminhalt: Der Sequenzdiagramm-Rahmen <code>sd SporadicFrame</code> mit den Lebenslinien <code>PduR::PduR</code> und <code>LinIf::LinIf</code>, den Nachrichten <code>LinIf_Transmit</code> inklusive Parametern und Rückkehr sowie den internen Aktionen <code>CheckId</code> und <code>SetFlag</code> entfällt vollständig.\n</li><li>Darstellungsumfang: Die Bildfassung enthält ausschließlich die Notizbox mit <code>Status:Proposed by WPII-2.1.1 as per LinIf SWS 1.1.2</code>, <code>Description:</code> und <code>Comments:</code>.\n</li></ul>"}]};
